package ocr

import (
	"image/png"
	"os"
	"strconv"
	"strings"
	"testing"
)

func loadChl(t *testing.T) []uint8 {
	t.Helper()
	f, err := os.Open("testdata/chl.png")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	img, err := png.Decode(f)
	if err != nil {
		t.Fatal(err)
	}
	return imageToRGB(img)
}

// TestChlGolden checks the full pipeline against the reference engine output
// (golden_chl.txt, generated by the C++ NEON engine with rotated-quad det).
// The Go engine is fp32 end to end (the C++ one stored body weights as fp16),
// so scores may differ slightly — text must match exactly, boxes within 2px.
func TestChlGolden(t *testing.T) {
	rgb := loadChl(t)
	lines, err := RecognizeRGB(rgb, 928, 306)
	if err != nil {
		t.Fatal(err)
	}
	golden, err := os.ReadFile("testdata/golden_chl.txt")
	if err != nil {
		t.Fatal(err)
	}
	var gt []struct {
		text           string
		x0, y0, x1, y1 float64
	}
	for _, ln := range strings.Split(string(golden), "\n") {
		ln = strings.TrimSpace(ln)
		if ln == "" || strings.HasPrefix(ln, "#") {
			continue
		}
		// "[0.96|1.00] (525,3 582,36) 1/1"
		rest := ln[strings.Index(ln, "(")+1:]
		coords := rest[:strings.Index(rest, ")")]
		text := strings.TrimSpace(rest[strings.Index(rest, ")")+1:])
		parts := strings.Fields(coords)
		a := strings.Split(parts[0], ",")
		b := strings.Split(parts[1], ",")
		var c [4]float64
		c[0], _ = strconv.ParseFloat(a[0], 64)
		c[1], _ = strconv.ParseFloat(a[1], 64)
		c[2], _ = strconv.ParseFloat(b[0], 64)
		c[3], _ = strconv.ParseFloat(b[1], 64)
		gt = append(gt, struct {
			text           string
			x0, y0, x1, y1 float64
		}{text, c[0], c[1], c[2], c[3]})
	}
	if len(gt) != 9 {
		t.Fatalf("golden parse: got %d lines, want 9", len(gt))
	}
	if len(lines) != len(gt) {
		for _, l := range lines {
			t.Logf("got: [%.2f|%.2f] (%.0f,%.0f %.0f,%.0f) %q", l.DetScore, l.RecScore,
				l.Box[0], l.Box[1], l.Box[4], l.Box[5], l.Text)
		}
		t.Fatalf("got %d lines, want %d", len(lines), len(gt))
	}
	for i, l := range lines {
		g := gt[i]
		if l.Text != g.text {
			t.Errorf("line %d text %q, want %q", i, l.Text, g.text)
		}
		dx0 := abs(l.Box[0] - g.x0)
		dy0 := abs(l.Box[1] - g.y0)
		dx1 := abs(l.Box[4] - g.x1)
		dy1 := abs(l.Box[5] - g.y1)
		if dx0 > 2 || dy0 > 2 || dx1 > 2 || dy1 > 2 {
			t.Errorf("line %d %q box (%.0f,%.0f %.0f,%.0f), want (%.0f,%.0f %.0f,%.0f)",
				i, l.Text, l.Box[0], l.Box[1], l.Box[4], l.Box[5], g.x0, g.y0, g.x1, g.y1)
		}
		if l.DetScore < 0.5 || l.RecScore < 0.5 {
			t.Errorf("line %d %q suspicious scores det=%.2f rec=%.2f", i, l.Text, l.DetScore, l.RecScore)
		}
	}
}

func abs(v float64) float64 {
	if v < 0 {
		return -v
	}
	return v
}

func TestModelLoad(t *testing.T) {
	m, err := loadModel()
	if err != nil {
		t.Fatal(err)
	}
	if n := len(m.det.layers); n != 84 {
		t.Errorf("det layers = %d, want 84", n)
	}
	if n := len(m.rec.layers); n != 37 {
		t.Errorf("rec layers = %d, want 37", n)
	}
	if n := len(m.charset); n != 6904 {
		t.Errorf("charset = %d, want 6904", n)
	}
	// every weight offset must be in range
	for _, nd := range []*netDef{m.det, m.rec} {
		for i, ly := range nd.layers {
			if ly.woff != noOff && (ly.woff < 0 || ly.woff >= len(m.weights)) {
				t.Errorf("net layer %d: woff %d out of range", i, ly.woff)
			}
			if ly.hasBias && (ly.boff < 0 || ly.boff >= len(m.biases)) {
				t.Errorf("net layer %d: boff %d out of range", i, ly.boff)
			}
		}
	}
}
